@dataclass(frozen=True)
class ScaledConfig:
    vertex_min: int
    vertex_max: int
    edge_max: int
    cost_max: int
    resource_max: int
    hop_limit: int
    class_count: int
    fuel_per_test: int = 30_000_000
    reference_steps: int = 50_000_000

    def validate(self) -> None:
        if not 4 <= self.vertex_min <= self.vertex_max <= 64:
            raise ValueError("vertex range must lie in [4, 64]")
        if not self.vertex_max <= self.edge_max <= 512:
            raise ValueError("edge_max must lie in [vertex_max, 512]")
        if not 2 <= self.hop_limit <= min(16, self.vertex_min - 1):
            raise ValueError("hop_limit must lie in [2, min(16, vertex_min - 1)]")
        if not 3 <= self.class_count <= 8 or not 1 <= self.cost_max <= 1_000 or not 1 <= self.resource_max <= 64:
            raise ValueError("class/cost/resource parameters out of range")

    def as_list(self) -> list[int]:
        return [self.vertex_min, self.vertex_max, self.edge_max, self.cost_max, self.resource_max,
                self.hop_limit, self.class_count, self.fuel_per_test, self.reference_steps]


