def scaled_task_spec(config: ScaledConfig, instance_root: bytes) -> list[int]:
    config.validate()
    sampler = CoordinateSampler(instance_root)
    required = sampler.u("lite/required-class", 0, 0, config.class_count - 1)
    forbidden = (required + 1 + sampler.u("lite/forbidden-offset", 0, 0, config.class_count - 2)) % config.class_count
    budget = config.hop_limit * max(1, config.resource_max // 2)
    return [1, 0, config.vertex_min, config.vertex_max, config.vertex_min - 1, config.edge_max,
            config.cost_max, config.resource_max, budget, config.hop_limit, config.class_count,
            1 << required, 1 << forbidden]


def scaled_challenge(config: ScaledConfig, instance_root: bytes, ticket_id: bytes = bytes(32)) -> ScaledChallenge:
    task = scaled_task_spec(config, instance_root)
    examples = []
    for index in range(2):
        root = hash_bytes(SCALED_CASE, (instance_root, b"public", u32_be(index)))
        case_input = construct_input(1, task, root, 20 + index)
        examples.append([case_input, reference_evaluate(task, case_input, step_limit=config.reference_steps)])
    challenge_id = hash_bytes(
        SCALED_CHALLENGE_ID, (encode([0, "GRAPH-ROUTE-L1", config.as_list(), task, examples, ticket_id]),)
    )
    return ScaledChallenge(config, instance_root, task, examples, challenge_id, ticket_id)


@dataclass(frozen=True)
class Case:
    ordinal: int
    input_bytes: bytes
    expected_bytes: bytes


def scaled_cases(challenge: ScaledChallenge, seed: bytes, count: int) -> list[Case]:
    cases: list[Case] = []
    ordinal = 0
    while len(cases) < count and ordinal < 4 * count:
        root = hash_bytes(SCALED_CASE, (seed, challenge.challenge_id, u32_be(ordinal)))
        try:
            case_input = construct_input(1, challenge.task_spec, root, ordinal % HIDDEN_PROFILE_COUNT)
            expected = reference_evaluate(challenge.task_spec, case_input, step_limit=challenge.config.reference_steps)
        except (GenerationFailed, ReferenceEvaluationFailed):
            ordinal += 1
            continue
        data = encode(case_input)
        if len(data) <= challenge.profile.input_bytes:
            cases.append(Case(ordinal, data, encode(expected)))
        ordinal += 1
    if len(cases) != count:
        raise ValueError("could not generate the requested number of scaled cases")
    return cases


def static_check(module_bytes: bytes, profile: ResourceProfile) -> tuple[str, object, int]:
    """Frozen static passes (canonical module, features, host surface, core, resources)."""

    if len(module_bytes) > profile.module_bytes:
        return "MODULE_TOO_LARGE", None, -1
    try:
        module = decode_module(module_bytes)
    except WasmStructuralError:
        return "MALFORMED_WASM", None, -1
    if encode_module(module) != module_bytes:
        return "NON_CANONICAL_WASM", None, -1
    try:
        validate_feature_profile(module)
        solve_index = validate_host_surface(module, profile)
        validate_resources(module, validate_core(module), profile)
    except WasmFeatureError:
        return "DISALLOWED_FEATURE", None, -1
    except WasmHostSurfaceError:
        return "INVALID_IMPORT_EXPORT", None, -1
    except WasmCoreValidationError:
        return "MALFORMED_WASM", None, -1
    except WasmResourceError:
        return "RESOURCE_PROFILE_VIOLATION", None, -1
    return "OK", module, solve_index


@dataclass(frozen=True)
class RunResult:
    valid: bool
    reason: str
    fuel: int
    per_case_fuel: tuple[int, ...]


def run_cases(
    challenge: ScaledChallenge,
    module_bytes: bytes,
    cases: list[Case],
    exhaustion_penalty: int | None = None,
) -> RunResult:
    """Run shared cases. By default any runtime failure invalidates the solver.

    `exhaustion_penalty` (PROPOSAL, not used by any season unless a manifest
    opts in): a case that exhausts the per-test fuel cap is charged this many
    fuel units instead of invalidating the solver ("time limit exceeded").
    Wrong or malformed output, traps and every other failure still invalidate.
    """

    from ares_lite._core.code_synth.verifier import VerifierError

    profile = challenge.profile
    reason, module, solve_index = static_check(module_bytes, profile)
    if reason != "OK":
        return RunResult(False, reason, 0, ())
    remaining = profile.fuel_per_reveal
    per_case = []
    for case in cases:
        output_ptr = 16 * ((len(case.input_bytes) + 15) // 16)
        output_cap = min(profile.output_bytes, profile.memory_pages * 65_536 - output_ptr)
        try:
            run = execute(module, solve_index, profile, case.input_bytes, output_ptr, output_cap, remaining)
        except RuntimeFailure as failure:
            if exhaustion_penalty is not None and failure.error is VerifierError.FUEL_EXHAUSTED:
                per_case.append(exhaustion_penalty)
                remaining -= failure.fuel_charged
                continue
            return RunResult(False, f"{failure.error.name}@{case.ordinal}", sum(per_case) + failure.fuel_charged, tuple(per_case))
        per_case.append(run.fuel_charged)
        remaining = run.reveal_fuel_remaining
        returned = run.return_value - (1 << 32) if run.return_value >= 1 << 31 else run.return_value
        if not 0 <= returned <= output_cap:
            return RunResult(False, f"INVALID_RETURN@{case.ordinal}", sum(per_case), tuple(per_case))
        if run.memory[output_ptr : output_ptr + returned] != case.expected_bytes:
            return RunResult(False, f"WRONG_OUTPUT@{case.ordinal}", sum(per_case), tuple(per_case))
    return RunResult(True, "OK", sum(per_case), tuple(per_case))


def instance_root_for(manifest_hash: bytes, beacon: bytes) -> bytes:
    return hash_bytes(SCALED_INSTANCE_ROOT, (manifest_hash, beacon))


